import { useEffect } from "react"
import { useNavigate, useParams } from "react-router-dom"
import { useDispatch, useSelector } from "react-redux"
import { getInfo } from "../store/CounterSlice"
import type { RootState } from "../store/store"

export default function Info() {
  const { id } = useParams()
  const navigate = useNavigate()
  const dispatch = useDispatch()
  const { data, infoUser } = useSelector((state: RootState) => state.data)

  useEffect(() => {
    dispatch(getInfo(Number(id)))
  }, [dispatch, id])

  const user = data.find((el) => el.id === Number(id)) ||
    (infoUser?.id === Number(id) ? infoUser : null)

  if (!user) return <p>User not found</p>
  return (
    <div>
      <button onClick={() => navigate(-1)}>Back</button>
      <h2>{user.name}</h2>
      <p>Age: {user.age}</p>
      <p>{user.status ? "Online" : "Offline"}</p>
      <p>{user.isCompleted ? "Completed" : "Not completed"}</p>
      {user.image && <img src={user.image} alt={user.name} />}
    </div>
  )
}

