import { atom } from "jotai"

export type User = {
  name: string
  age: number
  id: number
  status: boolean
  image: string
  isCompleted?: boolean
}

export const dataAtom = atom<User[]>([
    {
      id: 1,
      name: "Ali",
      age: 22,
      status: true,
      image: "https://i.pravatar.cc/150?img=1",
    },
    {
      id: 2,
      name: "Umar",
      age: 25,
      status: false,
      image: "https://i.pravatar.cc/150?img=2",
    },
    {
      id: 3,
      name: "Faridun",
      age: 19,
      status: true,
      image: "https://i.pravatar.cc/150?img=3",
    },
    {
      id: 4,
      name: "Samir",
      age: 28,
      status: false,
      image: "https://i.pravatar.cc/150?img=4",
    },
    {
      id: 5,
      name: "Dilshod",
      age: 24,
      status: true,
      image: "https://i.pravatar.cc/150?img=5",
    },
  ])
export const infoAtom = atom<User | null>(null)
export const searchAtom = atom("")
export const pageAtom = atom(1)
export const pageSizeAtom = atom(2)

export const AddUserAtom = atom(null, (get, set, user: User) => {
  set(dataAtom, [user, ...get(dataAtom)])
})

export const EditUserAtom = atom(null, (get, set, user: User) => {
  set(dataAtom, get(dataAtom).map((el) =>
    el.id === user.id ? user : el
  ))
})

export const deleteUserAtom = atom(null, (get, set, id: number) => {
  set(dataAtom, get(dataAtom).filter((el) => el.id !== id))
})

export const getInfoAtom = atom(null, (get, set, id: number) => {
  set(infoAtom, get(dataAtom).find((el) => el.id === id) || null)
})

export const setSearchAtom = atom(null, (_get, set, search: string) => {
  set(searchAtom, search)
  set(pageAtom, 1)
})

export const filteredAtom = atom((get) =>
  get(dataAtom).filter((el) =>
    el.name.toLowerCase().includes(get(searchAtom).toLowerCase())
  )
)

export const paginatedAtom = atom((get) =>
  get(filteredAtom).slice(
    (get(pageAtom) - 1) * get(pageSizeAtom),
    get(pageAtom) * get(pageSizeAtom)
  )
)

export const isCompletedAtom = atom(null, (get, set, id: number) => {
  set(dataAtom, get(dataAtom).map((el) =>
    el.id === id ? { ...el, isCompleted: !el.isCompleted } : el
  ))
})

export const addImgAtom = atom(null, (get, set, user: { id: number; image: string }) => {
  set(dataAtom, get(dataAtom).map((el) =>
    el.id === user.id ? { ...el, image: user.image } : el
