import { useEffect, useState } from "react"
import { useNavigate, useParams } from "react-router-dom"
import { useDispatch, useSelector } from "react-redux"
import { getByIdData } from "../store/counterSlice"

export default function Info() {
  const { id } = useParams()
  const navigate = useNavigate()
  const dispatch = useDispatch()
  const [loading, setLoading] = useState(true)
  const { todoinfo } = useSelector((store: any) => store.todo)

  useEffect(() => {
    async function LoadInfo() {
      if (!id) return
      setLoading(true)
      await dispatch(getByIdData(id))
      setLoading(false)
    }
    LoadInfo()
  }, [id, dispatch])

  if (loading) return <p>Loading...</p>
  if (!todoinfo || String(todoinfo.id) !== id) return <p>Todo not found</p>
  return (
    <div>
      <button onClick={() => navigate(-1)}>Back</button>
      <h2>{todoinfo.name}</h2>
      <p>{todoinfo.description}</p>
      <p>{todoinfo.isCompleted ? "Completed" : "Not completed"}</p>
      {todoinfo.images?.map((img: any) => (
        <img key={img.id} src={"https://to-dos-api.softclub.tj/images/" + img.imageName} alt={todoinfo.name} />
      ))}
    </div>
  )
}

