import { useEffect, useState } from "react"
import { useNavigate, useParams } from "react-router-dom"
import { useAtomValue, useSetAtom } from "jotai"
import { GetInfoAtom, infoUserAtom } from "../store/jotaiStore"

export default function Info() {
  const { id } = useParams()
  const navigate = useNavigate()
  const [loading, setLoading] = useState(true)
  const infoUser = useAtomValue(infoUserAtom)
  const getInfo = useSetAtom(GetInfoAtom)

  useEffect(() => {
    async function LoadInfo() {
      if (!id) return
      setLoading(true)
      await getInfo(id)
      setLoading(false)
    }
    LoadInfo()
  }, [id, getInfo])

  if (loading) return <p>Loading...</p>
  if (!infoUser || String(infoUser.id) !== id) return <p>Todo not found</p>
  return (
    <div>
      <button onClick={() => navigate(-1)}>Back</button>
      <h2>{infoUser.name}</h2>
      <p>{infoUser.description}</p>
      <p>{infoUser.isCompleted ? "Completed" : "Not completed"}</p>
      {infoUser.images?.map((img: any) => (
        <img key={img.id} src={"https://to-dos-api.softclub.tj/images/" + img.imageName} alt={infoUser.name} />
      ))}
    </div>
  )
}

import { createBrowserRouter, RouterProvider } from "react-router-dom"
import Layout from "./layout/Layout"
import Jotai from "./pages/Jotai"
import About from "./pages/About"
